package com.citacloud.springboot.contacloud.app.views;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.OrigenMovimientoInventario;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.*;import com.vaadin.flow.component.button.*;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.datepicker.DatePicker;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.notification.Notification;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.select.Select;import com.vaadin.flow.component.tabs.*;import com.vaadin.flow.component.textfield.TextField;import com.vaadin.flow.data.value.ValueChangeMode;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;
import com.vaadin.flow.server.StreamResource;import com.vaadin.flow.server.VaadinSession;
import org.slf4j.Logger;import org.slf4j.LoggerFactory;
import java.io.ByteArrayInputStream;import java.math.BigDecimal;import java.text.DecimalFormat;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

@Route(value="inventario/movimientos",layout=MainLayout.class) @PageTitle("Movimientos de inventario | ContaCloud") @PermitAll
public class MovimientosInventarioView extends VerticalLayout implements BeforeEnterObserver {
 private static final Logger LOGGER=LoggerFactory.getLogger(MovimientosInventarioView.class);
 private static final DateTimeFormatter DATE_TIME=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");private static final DecimalFormat NUMBER=new DecimalFormat("#,##0.####");
 private final MovimientoInventarioConsultaService service;private final MovimientoInventarioReporteService reports;private final EmpresaModuloService modules;private MovimientoInventarioCatalogosDto catalogs;
 private final Tab generalTab=new Tab("GENERAL"),kardexTab=new Tab("KARDEX");private final Div content=new Div();
 public MovimientosInventarioView(MovimientoInventarioConsultaService service,MovimientoInventarioReporteService reports,EmpresaModuloService modules){this.service=service;this.reports=reports;this.modules=modules;addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();add(new AppPageHeader("MOVIMIENTOS DE INVENTARIO","Consulta la trazabilidad de las entradas y salidas que modifican las existencias."));Tabs tabs=new Tabs(generalTab);if(can("inventario_movimientos.kardex"))tabs.add(kardexTab);tabs.setWidthFull();content.setWidthFull();tabs.addSelectedChangeListener(e->show(e.getSelectedTab()));add(tabs,content);}
 @Override public void beforeEnter(BeforeEnterEvent e){if(!modules.habilitado("INVENTARIO")||!can("inventario_movimientos.ver")){Notification.show("No tienes permiso para acceder a esta opción.");e.rerouteTo(DashboardView.class);return;}try{catalogs=service.catalogos();show(generalTab);}catch(RuntimeException ex){error(ex,"No fue posible cargar los movimientos de inventario.");}}
 private void show(Tab tab){if(catalogs==null)return;content.removeAll();content.add(tab==kardexTab?kardex():general());}

 private Component general(){
  VerticalLayout box=new VerticalLayout();box.setPadding(false);box.setWidthFull();
  TextField search=new TextField("Buscar");search.setPlaceholder("Producto, código, documento, referencia o movimiento...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);
  DatePicker from=date("Desde"),to=date("Hasta");
  ComboBox<MovimientoInventarioCatalogosDto.Opcion> branch=combo("Sucursal",catalogs.sucursales());
  ComboBox<MovimientoInventarioCatalogosDto.AlmacenOpcion> warehouse=warehouseCombo("Almacén",catalogs.almacenes());
  ComboBox<MovimientoInventarioCatalogosDto.ProductoOpcion> product=productCombo("Producto",catalogs.productos());
  Select<String> type=new Select<>();type.setLabel("Tipo");type.setItems("Todos","Entrada","Salida");type.setValue("Todos");
  Select<OrigenMovimientoInventario> origin=new Select<>();origin.setLabel("Origen");origin.setItems(OrigenMovimientoInventario.values());origin.setItemLabelGenerator(x->x==null?"":x.getEtiqueta());origin.setEmptySelectionAllowed(true);origin.setPlaceholder("Todos");
  AppActionButton pdf=new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Generar PDF",null);pdf.setVisible(can("inventario_movimientos.pdf"));setPdfAvailability(pdf,false);
  pdf.addClickListener(e->generatePdf(pdf,()->reports.generarGeneral(search.getValue(),from.getValue(),to.getValue(),id(branch),id(warehouse),id(product),typeValue(type),origin.getValue())));
  HorizontalLayout filters=new HorizontalLayout(search,from,to,branch,warehouse,product,type,origin,pdf);filters.addClassName("cc-filter-bar");filters.setAlignItems(Alignment.END);filters.setWidthFull();filters.expand(search);
  Div movements=valueCard("MOVIMIENTOS","0"),affected=valueCard("PRODUCTOS AFECTADOS","0");HorizontalLayout summary=new HorizontalLayout(movements,affected);summary.setWidthFull();summary.addClassName("cc-summary-grid");
  AppGrid<MovimientoInventarioDto> grid=grid();AppPagination[] pages=new AppPagination[1];
  Runnable load=()->{try{var r=pages[0].currentRequest();var result=service.general(search.getValue(),from.getValue(),to.getValue(),id(branch),id(warehouse),id(product),typeValue(type),origin.getValue(),r.page(),r.size());grid.setItems(result.pagina().getContent());pages[0].setTotal(result.pagina().getTotalElements());setValue(movements,result.resumen().movimientos());setValue(affected,result.resumen().productosAfectados());setPdfAvailability(pdf,result.pagina().getTotalElements()>0);}catch(RuntimeException ex){setPdfAvailability(pdf,false);error(ex,"No fue posible cargar los movimientos.");}};
  pages[0]=new AppPagination(r->load.run());search.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});for(HasValue<?,?> f:List.of(from,to,product,type,origin))f.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});branch.addValueChangeListener(e->{if(e.isFromClient()){warehouse.clear();warehouse.setItems(filterWarehouses(e.getValue()));pages[0].reset();load.run();}});warehouse.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});
  box.add(filters,summary,grid,pages[0]);load.run();return box;
 }

 private Component kardex(){
  VerticalLayout box=new VerticalLayout();box.setPadding(false);box.setWidthFull();
  ComboBox<MovimientoInventarioCatalogosDto.ProductoOpcion> product=productCombo("Producto *",catalogs.productos());
  ComboBox<MovimientoInventarioCatalogosDto.Opcion> branch=combo("Sucursal",catalogs.sucursales());
  ComboBox<MovimientoInventarioCatalogosDto.AlmacenOpcion> warehouse=warehouseCombo("Almacén",catalogs.almacenes());
  DatePicker from=date("Desde"),to=date("Hasta");
  AppActionButton pdf=new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Generar PDF",null);pdf.setVisible(can("inventario_movimientos.pdf"));setPdfAvailability(pdf,false);
  pdf.addClickListener(e->generatePdf(pdf,()->reports.generarKardex(id(product),id(branch),id(warehouse),from.getValue(),to.getValue())));
  HorizontalLayout filters=new HorizontalLayout(product,branch,warehouse,from,to,pdf);filters.addClassName("cc-filter-bar");filters.setAlignItems(Alignment.END);filters.setWidthFull();filters.expand(product);
  Div initial=valueCard("SALDO INICIAL","—"),entries=valueCard("ENTRADAS","—"),exits=valueCard("SALIDAS","—"),finalValue=valueCard("SALDO FINAL","—");HorizontalLayout summary=new HorizontalLayout(initial,entries,exits,finalValue);summary.setWidthFull();summary.addClassName("cc-summary-grid");
  AppGrid<MovimientoInventarioDto> grid=grid();AppPagination[] pages=new AppPagination[1];
  Runnable load=()->{if(product.getValue()==null){grid.setItems(List.of());pages[0].setTotal(0);setValue(initial,"—");setValue(entries,"—");setValue(exits,"—");setValue(finalValue,"—");setPdfAvailability(pdf,false);return;}try{var r=pages[0].currentRequest();var result=service.kardex(id(product),id(branch),id(warehouse),from.getValue(),to.getValue(),r.page(),r.size());grid.setItems(result.pagina().getContent());pages[0].setTotal(result.pagina().getTotalElements());setValue(initial,number(result.resumen().saldoInicial()));setValue(entries,number(result.resumen().entradas()));setValue(exits,number(result.resumen().salidas()));setValue(finalValue,number(result.resumen().saldoFinal()));setPdfAvailability(pdf,true);}catch(RuntimeException ex){setPdfAvailability(pdf,false);error(ex,"No fue posible cargar el Kardex.");}};
  pages[0]=new AppPagination(r->load.run());for(HasValue<?,?> f:List.of(product,from,to))f.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});branch.addValueChangeListener(e->{if(e.isFromClient()){warehouse.clear();warehouse.setItems(filterWarehouses(e.getValue()));pages[0].reset();load.run();}});warehouse.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});
  box.add(filters,summary,grid,pages[0]);load.run();return box;
 }

 private AppGrid<MovimientoInventarioDto> grid(){AppGrid<MovimientoInventarioDto> g=new AppGrid<>(MovimientoInventarioDto.class);g.addColumn(x->time(x.fechaEfectiva())).setHeader("Fecha/Hora").setAutoWidth(true);g.addComponentColumn(this::document).setHeader("Documento").setAutoWidth(true);g.addColumn(x->x.producto()+" · "+x.productoCodigo()).setHeader("Producto").setFlexGrow(1);g.addColumn(MovimientoInventarioDto::almacen).setHeader("Almacén").setFlexGrow(1);g.addColumn(MovimientoInventarioDto::tipo).setHeader("Tipo").setAutoWidth(true);g.addColumn(x->amount(x.entrada())).setHeader("Entrada").setAutoWidth(true);g.addColumn(x->amount(x.salida())).setHeader("Salida").setAutoWidth(true);g.addColumn(x->number(x.existenciaPosterior())).setHeader("Existencia").setAutoWidth(true);if(can("inventario_movimientos.detalle"))g.addComponentColumn(x->new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver movimiento",e->detail(x.id()))).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);g.setEmptyStateText("No hay movimientos con los filtros seleccionados.");return g;}
 private Component document(MovimientoInventarioDto x){if(canOrigin(x.origen())){Button b=new Button(x.documento());b.addThemeVariants(ButtonVariant.LUMO_TERTIARY_INLINE);b.addClickListener(e->openOrigin(x.origen(),x.documentoId()));return b;}return new Span(x.documento());}
 private void detail(UUID id){try{var x=service.detalle(id);Dialog d=dialog("MOVIMIENTO DE INVENTARIO");Div heading=new Div(new H2(x.numero()),new Span(x.estado()));heading.addClassName("cc-detail-heading");HorizontalLayout info=new HorizontalLayout(new AppDetailSection("INFORMACIÓN GENERAL").field("Fecha efectiva",time(x.fechaEfectiva())).field("Tipo",x.tipo()).field("Origen",x.origen().getEtiqueta()).field("Documento",x.documento()).field("Estado",x.estado()),new AppDetailSection("PRODUCTO").field("Producto",x.producto()).field("Código",x.productoCodigo()).field("Unidad",x.unidad()).field("Almacén",x.almacen()).field("Sucursal",x.sucursal()));info.setWidthFull();info.setAlignItems(Alignment.STRETCH);info.getChildren().forEach(c->c.getElement().getStyle().set("flex","1 1 0"));d.add(heading,info,new AppDetailSection("MOVIMIENTO").field("Existencia anterior",number(x.existenciaAnterior())).field("Entrada",amount(x.entrada())).field("Salida",amount(x.salida())).field("Existencia posterior",number(x.existenciaPosterior())).field("Cantidad de origen",number(x.cantidadOrigen())).field("Factor de conversión",number(x.factorConversion())).field("Cantidad base",number(x.cantidadBase())),new AppDetailSection("ORIGEN").field("Documento",x.documento()).field("Tipo",x.origen().getEtiqueta()).field("Referencia",display(x.referencia())).field("Proveedor",display(x.proveedor())),new AppDetailSection("AUDITORÍA").field("Generado por",x.generadoPor()).field("Registrado",time(x.registradoEn())).field("Reversión de",display(x.movimientoOriginalNumero())).field("Revertido por",display(x.movimientoReversionNumero())));d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible consultar el movimiento.");}}
 private void openOrigin(OrigenMovimientoInventario origin,UUID id){if(origin==OrigenMovimientoInventario.RECEPCION||origin==OrigenMovimientoInventario.REVERSION)UI.getCurrent().navigate("recepciones",QueryParameters.simple(Map.of("id",id.toString())));}
 private boolean canOrigin(OrigenMovimientoInventario origin){return(origin==OrigenMovimientoInventario.RECEPCION||origin==OrigenMovimientoInventario.REVERSION)&&can("recepciones.ver");}
 private List<MovimientoInventarioCatalogosDto.AlmacenOpcion> filterWarehouses(MovimientoInventarioCatalogosDto.Opcion branch){return catalogs.almacenes().stream().filter(x->branch==null||branch.id().equals(x.sucursalId())).toList();}
 private void generatePdf(AppActionButton button,java.util.function.Supplier<ArchivoPdfDto> generator){button.setEnabled(false);button.setTooltipText("Generando PDF...");button.getElement().setAttribute("aria-busy","true");try{ArchivoPdfDto file=generator.get();StreamResource resource=new StreamResource(file.nombreArchivo(),()->new ByteArrayInputStream(file.contenido()));resource.setContentType("application/pdf");resource.setCacheTime(0);var registration=VaadinSession.getCurrent().getResourceRegistry().registerResource(resource);UI.getCurrent().getPage().open(registration.getResourceUri().toString(),"_blank");}catch(RuntimeException ex){error(ex,"No fue posible generar el PDF. Intente nuevamente.");}finally{button.getElement().removeAttribute("aria-busy");button.setTooltipText("Generar PDF");button.setEnabled(true);}}
 private static void setPdfAvailability(AppActionButton button,boolean available){boolean allowed=can("inventario_movimientos.pdf");button.setEnabled(allowed&&available);button.setTooltipText(available?"Generar PDF":"No hay movimientos para generar el reporte.");}
 private static Div valueCard(String label,String value){Div c=new Div(new Span(label),new H2(value));c.addClassNames("cc-card","cc-summary-card");return c;}private static void setValue(Div card,Object value){((H2)card.getComponentAt(1)).setText(String.valueOf(value));}private static Dialog dialog(String title){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth("min(1100px, 96vw)");return d;}private static <T>ComboBox<T> comboBase(String label,List<T> items){ComboBox<T> c=new ComboBox<>(label);c.setItems(items);c.setClearButtonVisible(true);return c;}private static ComboBox<MovimientoInventarioCatalogosDto.Opcion> combo(String l,List<MovimientoInventarioCatalogosDto.Opcion> i){var c=comboBase(l,i);c.setItemLabelGenerator(MovimientoInventarioCatalogosDto.Opcion::nombre);return c;}private static ComboBox<MovimientoInventarioCatalogosDto.AlmacenOpcion> warehouseCombo(String l,List<MovimientoInventarioCatalogosDto.AlmacenOpcion> i){var c=comboBase(l,i);c.setItemLabelGenerator(MovimientoInventarioCatalogosDto.AlmacenOpcion::nombre);return c;}private static ComboBox<MovimientoInventarioCatalogosDto.ProductoOpcion> productCombo(String l,List<MovimientoInventarioCatalogosDto.ProductoOpcion> i){var c=comboBase(l,i);c.setItemLabelGenerator(x->x.codigo()+" · "+x.nombre());return c;}private static DatePicker date(String label){DatePicker d=new DatePicker(label);d.setLocale(new Locale("es","DO"));d.setPlaceholder("DD/MM/YYYY");d.setClearButtonVisible(true);return d;}private static UUID id(ComboBox<? extends Object> c){Object x=c.getValue();if(x instanceof MovimientoInventarioCatalogosDto.Opcion o)return o.id();if(x instanceof MovimientoInventarioCatalogosDto.AlmacenOpcion o)return o.id();if(x instanceof MovimientoInventarioCatalogosDto.ProductoOpcion o)return o.id();return null;}private static String typeValue(Select<String> s){return switch(s.getValue()){case"Entrada"->"ENTRADA";case"Salida"->"SALIDA";default->"TODOS";};}private static String time(OffsetDateTime value){return value==null?"—":DATE_TIME.format(value.atZoneSameInstant(ZoneId.systemDefault()));}private static String number(BigDecimal value){return value==null?"—":NUMBER.format(value);}private static String amount(BigDecimal value){return value==null||value.signum()==0?"—":number(value);}private static String display(String v){return v==null||v.isBlank()?"—":v;}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static void error(RuntimeException ex,String fallback){LOGGER.error(fallback,ex);String m=ex instanceof ReglaNegocioException||ex instanceof RecursoNoEncontradoException?ex.getMessage():fallback;Notification.show(m==null||m.isBlank()?fallback:m);}
}
